(()=>{const out=[];for(const kind of ['webgl','webgl2'])for(const [name,format,size]of [['WEBGL_compressed_texture_s3tc',33777,8],['EXT_texture_compression_rgtc',36283,8],['EXT_texture_compression_bptc',36492,16]]){const g=new OffscreenCanvas(4,4).getContext(kind),e=g.getExtension(name),t=g.createTexture(),r={kind,name,formats:Array.from(g.getParameter(g.COMPRESSED_TEXTURE_FORMATS)),errors:[]};g.bindTexture(g.TEXTURE_2D,t);for(const [w,h,n]of [[4,4,size],[4,4,size-1],[3,3,size],[2,2,size],[1,1,size],[0,0,0],[8,4,size*2]]){g.compressedTexImage2D(g.TEXTURE_2D,0,format,w,h,0,new Uint8Array(n));r.errors.push(g.getError())}for(const [x,y,w,h,n]of [[0,0,4,4,size],[4,0,4,4,size],[1,0,4,4,size],[0,0,3,4,size],[0,0,4,4,size-1],[8,0,4,4,size]]){g.compressedTexSubImage2D(g.TEXTURE_2D,0,x,y,w,h,format,new Uint8Array(n));r.errors.push(g.getError())}out.push(r)}return out})()
